        }
    }

    private void requireVersion(ChunkIntake intake, int expectedVersion) {
        if (intake.version() != expectedVersion) {
            throw ApiException.conflict("期望版本与当前版本不一致: 期望 " + expectedVersion
                    + " 当前 " + intake.version());
        }
    }

